public static function create_tables() {
    global $wpdb;
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    $charset_collate = $wpdb->get_charset_collate();
    $table_name = $wpdb->prefix . 'terso_commissions';

    $sql = "CREATE TABLE {$table_name} (
        id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
        affiliate_id bigint(20) unsigned NOT NULL,
        order_id bigint(20) unsigned DEFAULT 0 NOT NULL,
        amount decimal(12,4) DEFAULT '0.0000' NOT NULL,
        currency varchar(10) DEFAULT 'USD' NOT NULL,
        status varchar(30) DEFAULT 'pending' NOT NULL,
        created_at datetime DEFAULT CURRENT_TIMESTAMP NOT NULL,
        updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,
        PRIMARY KEY  (id),
        KEY affiliate_status (affiliate_id, status),
        KEY order_id (order_id)
    ) {$charset_collate};";

    dbDelta( $sql );
    update_option( 'terso_db_version', '1.0.0' );
}

